import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    val = {'I': 1, 'V': 5, 'X': 10, 'L': 50}
    entries = []
    for i in range(n):
        name = data[1 + 2 * i]
        num = data[2 + 2 * i]
        total = 0
        for idx, ch in enumerate(num):
            v = val[ch]
            if idx + 1 < len(num) and val[num[idx + 1]] > v:
                total -= v
            else:
                total += v
        entries.append((name, total, num))
    entries.sort(key=lambda e: (e[0], e[1]))
    print('\n'.join(e[0] + ' ' + e[2] for e in entries))

